mapper.update:
UPDATE dodo_restock_subscription
SET scheme_id = #{schemeId}, state = #{state}, generation = #{generation}, version = #{version},
    subscribed_at = #{subscribedAt}, expires_at = #{expiresAt}, next_check_at = #{nextCheckAt}, updated_at = #{updatedAt}
WHERE id = #{id} AND user_id = #{userId} AND store_id = #{storeId} AND shop_id = #{shopId}

mapper.select:
SELECT * FROM dodo_restock_subscription WHERE id = #{id}
AND user_id = #{userId}
AND store_id = #{storeId}
AND shop_id = #{shopId}
FOR UPDATE

SELECT id FROM dodo_restock_subscription WHERE state = 'WAITING'
AND next_check_at <= CURRENT_TIMESTAMP(3)
AND store_id = #{storeId}
AND goods_id = #{goodsId}
ORDER BY next_check_at, id LIMIT #{limit}

SELECT s.*, n.id AS notification_id, n.content, n.delivery_state, n.read_at, n.clicked_at
FROM dodo_restock_subscription s LEFT JOIN dodo_restock_notice n ON n.subscription_id = s.id AND n.generation = s.generation
WHERE s.user_id = #{userId} AND s.store_id = #{storeId} AND s.shop_id = #{shopId}
ORDER BY s.updated_at DESC, s.id LIMIT #{limit} OFFSET #{start}

SELECT goods_id FROM dodo_restock_subscription
WHERE user_id = #{userId} AND store_id = #{storeId} AND shop_id = #{shopId}
AND state = 'WAITING' AND expires_at > CURRENT_TIMESTAMP(3)
